using System.Globalization;
using System.IO;
namespace PhotoTrail.Windows;
internal sealed record PhotoGpxRow(string Path,string Hash,string? SidecarHash,long Revision,string InspectionError,string Reason,TrackPoint? Point=null,string? Name=null);
internal sealed record PhotoGpxPlan(PhotoGpxRow[] Rows,ImportSource[] Sources,TrackData Data,string[] Names,decimal GapSeconds) {
 internal int Count=>Names.Length;
 internal static MapPoint? Point(PhotoDocument doc,out string reason){bool xmp=doc.Value("XMP-exif:GPSLatitude").Length>0||doc.Value("XMP-exif:GPSLongitude").Length>0||doc.Draft.ContainsKey("XMP-exif:GPSLatitude")||doc.Draft.ContainsKey("XMP-exif:GPSLongitude");string Read(string tag)=>doc.Embedded.TryGetProperty(tag,out var v)?PhotoDocument.Text(v):"";string a=xmp?doc.Value("XMP-exif:GPSLatitude"):Read("GPS:GPSLatitude"),b=xmp?doc.Value("XMP-exif:GPSLongitude"):Read("GPS:GPSLongitude");if(a.Length==0&&b.Length==0){reason="缺GPS";return null;}var p=doc.Position();if(p is null){reason="非法GPS或基准";return null;}var datum=xmp?doc.Value("XMP-exif:GPSMapDatum"):Read("GPS:GPSMapDatum");if(datum.Replace("-","").Replace(" ","").ToUpperInvariant()!="WGS84"){reason="未知基准";return null;}reason="";return p;}
 static double? Elevation(PhotoDocument doc){bool xmp=doc.Value("XMP-exif:GPSLatitude").Length>0||doc.Value("XMP-exif:GPSLongitude").Length>0||doc.Draft.ContainsKey("XMP-exif:GPSLatitude")||doc.Draft.ContainsKey("XMP-exif:GPSLongitude");string Read(string suffix)=>xmp?doc.Value("XMP-exif:"+suffix):doc.Embedded.TryGetProperty("GPS:"+suffix,out var v)?PhotoDocument.Text(v):"";var text=Read("GPSAltitude");if(text.Length==0)return null;var reference=Read("GPSAltitudeRef");if(!double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out var height)||!double.IsFinite(height)||reference is not("0" or "1"))throw new ArgumentException("非法海拔/方向");return reference=="1"?-Math.Abs(height):height;}
 internal static async Task<PhotoGpxPlan> CreateAsync(PhotoDocument[] docs,decimal gapSeconds=300,CancellationToken token=default){if(gapSeconds is <0 or >315576000||decimal.Truncate(gapSeconds*TimeSpan.TicksPerSecond)!=gapSeconds*TimeSpan.TicksPerSecond)throw new ArgumentException("断段间隔须0至315576000秒，最小100ns且不舍入。");if(docs.Length is <1 or >3000||docs.Select(d=>d.FilePath).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=docs.Length)throw new ArgumentException("请选择1至3000张独立照片。");var revisions=docs.Select(d=>d.DraftRevision).ToArray();var sources=new List<ImportSource>();foreach(var doc in docs){token.ThrowIfCancellationRequested();InplaceHistory.RequireClear(doc.SidecarPath is {} sidecar?[doc.FilePath,sidecar]:[doc.FilePath]);await doc.EnsureUnchangedAsync(token);sources.Add(ImportSource.Read(doc.FilePath));if(doc.SidecarPath is {} side)sources.Add(ImportSource.Read(side));}
 var texts=new string?[docs.Length];var errors=new string[docs.Length];for(int i=0;i<docs.Length;i++){try{texts[i]=BatchTrackMatch.Capture(docs[i]);if(texts[i] is {} raw)texts[i]=VerifiedPhotoDate.Bridge(raw);}catch(ArgumentException){errors[i]="非法主时间";}}
 var dates=await VerifiedPhotoDate.InspectAsync(texts.OfType<string>(),token);var rows=new List<PhotoGpxRow>();for(int i=0;i<docs.Length;i++){token.ThrowIfCancellationRequested();var d=docs[i];string reason=d.InspectionError.Length>0?"读取失败":errors[i]??"";MapPoint? p=null;TrackPoint? point=null;if(reason.Length==0)p=Point(d,out reason);if(reason.Length==0){if(texts[i] is null)reason="缺主时间（清除不回退）";else if(dates.GetValueOrDefault(texts[i]!) is not {} date)reason="非法主时间";else if(date.InstantLimitation is {} limit)reason=limit;else{try{point=new(p!.Longitude,p.Latitude,Elevation(d),date.Instant()!.Value);reason="有效";}catch(ArgumentException e){reason=e.Message;}}}rows.Add(new(d.FilePath,d.SourceHash,d.SidecarHash,revisions[i],d.InspectionError,reason,point,System.IO.Path.GetFileName(d.FilePath)));}
 var sorted=rows.Where(r=>r.Point is not null).OrderBy(r=>r.Point!.Time).ToArray();var segments=new List<IReadOnlyList<TrackPoint>>();var current=new List<TrackPoint>();long gapTicks=(long)(gapSeconds*TimeSpan.TicksPerSecond);TrackPoint? previous=null;foreach(var r in sorted){var p=r.Point!;if(previous is not null&&(p.Time!.Value-previous.Time!.Value).Ticks>gapTicks){segments.Add(current);current=[];}current.Add(p);previous=p;}if(current.Count>0)segments.Add(current);var plan=new PhotoGpxPlan(rows.ToArray(),sources.ToArray(),new(segments),sorted.Select(r=>r.Name!).ToArray(),gapSeconds);plan.Require(docs);return plan;
 }
 internal void Require(PhotoDocument[] docs){if(docs.Length!=Rows.Length)throw new IOException("照片GPX目标变化。");foreach(var source in Sources)source.RequireCurrent();foreach(var (d,i) in docs.Select((d,i)=>(d,i))){var r=Rows[i];if(d.FilePath!=r.Path||d.SourceHash!=r.Hash||d.SidecarHash!=r.SidecarHash||d.DraftRevision!=r.Revision||d.InspectionError!=r.InspectionError)throw new IOException("照片GPX来源或草稿变化；请重新生成预览。");}}
 internal async Task ExportAsync(PhotoDocument[] docs,string target,string name,CancellationToken token=default){if(Count==0)throw new InvalidOperationException("没有有效点，不能导出空成功文件。");if(name.Length>255||name.Any(char.IsControl))throw new ArgumentException("轨迹名称无效。");using var parents=SavePaths.LockParents(target);var guards=new List<FileStream>();try{foreach(var source in Sources)guards.Add(new(source.Path,FileMode.Open,FileAccess.Read,FileShare.Read));Require(docs);foreach(var d in docs)await d.EnsureUnchangedAsync(token);await TrackAdjustment.ExportAsync(Data,Rows[0].Path,target,token,()=>Require(docs),name,Names);}finally{foreach(var g in guards)g.Dispose();}}
}
